function startTurn(s,log){let p=s.players[s.turn];delete p.protectDestroy;delete p.protectSteal;delete p.returnOnLoss;delete p.untilNextRoll;delete p.leaderUsed;delete p.freeDrawUsed;s.ap=3+(p.kills.includes('145')?1:0);s.druidUsed=[];s.used=[];s.bonus=0;s.attackBonus=0;s.noChallenge=false;s.noModifiers=false;
if(p.leader==='165'){s.dice=[random(6)+1,random(6)+1];s.rollSeq=(s.rollSeq||0)+1;p.leaderRoll=s.dice[0]+s.dice[1];log(p.name+' — Kỳ Lân Bất Ổn: chỉ số '+p.leaderRoll);}
if(['173','174','175'].includes(p.leader)){choice(s,s.turn,p.leader,'leaderRole',[{player:s.turn,id:'option-hero'},{player:s.turn,id:p.leader==='175'?'option-challenge':'option-monster'}],{optional:true});}
}
