function visibleQueue(s,i,id,queue){while(queue.length){let j=queue.shift();if(s.players[j].hand.length){choice(s,i,id,'visibleCard',s.players[j].hand.map(id=>({player:j,id})),{queue,private:true});return;}}s.pending=null;}
function discardCollect(s,i,id,queue,collected){while(queue.length){let j=queue.shift();if(s.players[j].hand.length){handChoice(s,j,id,'collectDiscard',{origin:i,queue,collected});return;}}choice(s,i,id,'collectRecover',collected.filter(h=>s.discard.includes(h)).map(id=>({player:i,id})));}
function freeItem(s,i,id,item){let cursed=+item>=57&&+item<=63;choice(s,i,id,'freeEquip',s.players.flatMap((x,j)=>(cursed?j!==i:j===i)?x.party.filter(h=>!x.items[h]).map(id=>({player:j,id})):[]),{item,optional:true});}
function skill(s,p,id,total,log){let r=RULES[id];if(!r)fail('Thiếu dữ liệu kỹ năng anh hùng '+id);if(total<r[0]){if(p.kills.includes('124')){draw(s,p,1);log(p.name+' — Kẻ Xé Rạn San Hô: rút 1 lá');}let item=p.items[id];if(item==='75')draw(s,p,1);if(item==='79')s.bonus=(s.bonus||0)+2;if(item==='81')s.ap++;if(item==='62')removeHero(s,p,id,undefined,'sacrifice');log(p.name+' gieo '+total+' / '+r[0]+' — kỹ năng thất bại');return}if(p.kills.includes('132')){draw(s,p,1);log(p.name+' — Dương Thần Băng Giá: rút 1 lá');}let [,k,v]=r;if(k==='fill')draw(s,p,Math.max(0,v-p.hand.length));if(k==='destroy'){let targets=heroTargets(s,'destroy');if(targets.length)s.pending={type:'skillTarget',actor:s.players.indexOf(p),id,effect:k,remaining:v,targets};}if(['steal','sacrifice','returnItems','curseReturn'].includes(k)){let actor=s.players.indexOf(p),targets=s.players.flatMap((x,j)=>k==='returnItems'?(Object.keys(x.items).length?[{player:j,id:x.leader}]:[]):((k==='steal'?j!==actor&&!x.protectSteal:j===actor)?x.party.filter(h=>k!=='curseReturn'||(+x.items[h]>=57&&+x.items[h]<=63)).map(id=>({player:j,id})):[]));if(targets.length)s.pending={type:'skillTarget',actor,id,effect:k,targets};else {log(p.name+' — không có mục tiêu hợp lệ');return;}}if(k==='draw')draw(s,p,v);extraSkill(s,s.players.indexOf(p),id,k,v,log);if(AUTO_SKILLS.has(k))autoSkill(s,s.players.indexOf(p),id,k,v,log);if(k==='bonus')s.bonus=(s.bonus||0)+v;if(k==='attackBonus')s.attackBonus=(s.attackBonus||0)+v;if(k==='partyBonus')s.bonus=(s.bonus||0)+p.party.length;if(k==='monsterDraw')draw(s,p,s.players.reduce((a,x)=>a+x.kills.length,0));if(k==='itemDraw')draw(s,p,Object.keys(p.items).length);if(k==='shield')s.noChallenge=true;if(k==='recover'){let ids=s.discard.filter(id=>C[id].type===v);if(ids.length)s.pending={type:'recover',actor:s.players.indexOf(p),ids};}log(p.name+' gieo '+total+' / '+r[0]+' — kỹ năng thành công');}
