function botStep(s){let q=s.pending,j=['challenge','druidReact','modifierReact'].includes(q?.type)?q.responders[0]:q?q.actor:s.turn,p=s.players[j];if(!p?.bot||s.phase!=='play')return s;let call=(op,extra={})=>core(s,{op,token:p.token,rev:s.rev,...extra}).s;if(q?.type==='modifierReact'){if(q.recover)return call('modifierRecover',{id:s.discard[0]});let threshold=q.kind==='challenge'?(q.stage===1?(s.duel?.defense||0)+1:8):q.kind==='attack'?MON[q.id][0]:RULES[q.id]?.[0], reverse=q.kind==='attack'&&MON[q.id][6], win=n=>reverse?n<=threshold:n>=threshold;for(let id of p.hand){let c=C[id];if(c?.type!=='modifier'||modBase(id)==='191')continue;let cost=p.hand.find(h=>h!==id);if(['184','185'].includes(modBase(id))&&!cost)continue;for(let value of modifierValues(q,j,c,s))if(win(q.total)!==win(q.total+value)&&win(q.total+value)===(j===q.actor))return call('modifierPlay',{id,value,cost});}return call('modifierPass');}if(q?.type==='druidReact')return call(q.actor!==j?'druidMinus':'druidPass');if(q?.type==='challenge')return call(p.hand.includes('97')&&!challengeBlocked(s,q)&&random(4)===0?'challenge':'pass',{id:'97'});if(q?.type==='freeSkill')return call(RULES[q.id]?'freeSkill':'skipSkill');if(q?.type==='skillTarget'){let k=q.effect,beneficial=['auto:freeCard','auto:freeEquip','auto:revealDraw','auto:discardDraw','auto:endDraw','auto:steal','auto:takeTwoNoDraw','auto:destroyOrSteal','auto:leaderRole','auto:leaderDrawCount','auto:drawExtra','auto:destroyOne','auto:giveOrRefuse'].includes(k);let t=k==='auto:leaderDrawCount'?q.targets.at(-1):q.targets[0];if(k==='auto:freeCard'&&C[t.id]?.type==='magic'&&['86','88','89','94','96'].includes(t.id))beneficial=false;return q.optional&&!beneficial?call('skipEffect'):call('skillTarget',t);}if(q?.type==='recover')return call('recover',{id:q.ids[0]});if(q?.type==='rollBoost'){let o=q.options.find(o=>o.left>0),threshold=q.kind==='challenge'?(q.stage===1?(s.duel?.defense||0)+1:8):q.kind==='skill'?RULES[q.id]?.[0]:MON[q.id][0];let wants=q.kind==='attack'&&MON[q.id][6]?false:q.total<threshold;return wants&&o&&p.hand.length?call('rollBoost',{key:o.key,id:p.hand[0]}):call('rollPass');}if(q?.type==='attack')return call('resolve');if(q?.type==='counterChoice')return call('counterChoice',{draw:true});if(p.kills.includes('139')&&!p.freeDrawUsed)return call('monsterSkill',{id:'139'});if(!s.ap)return call('next');if(!p.leaderUsed&&((p.leader==='163'&&s.ap>=2&&s.discard.length)||(p.leader==='169'&&s.players.some((x,i)=>i!==j&&x.hand.length))))return call('leaderSkill');let monster=s.monsters.find(id=>MON[id]&&eligibleTeam(p,id)&&p.hand.filter(h=>!MON[id][5]||C[h].type===MON[id][5]).length>=(MON[id][4]||0));if(s.ap>=2&&monster)return call('attack',{id:monster,checked:true});let hero=p.hand.find(id=>C[id].type==='hero');if(hero)return call('play',{id:hero});let item=p.hand.find(id=>C[id].type==='item'&&!(+id>=57&&+id<=63)),h=p.party.find(id=>!p.items[id]);if(item&&h)return call('play',{id:item,targetPlayer:j,targetHero:h});let sk=p.party.find(id=>RULES[id]&&p.items[id]!=='58'&&(p.items[id]!=='63'||s.ap>=2)&&(!(s.used||[]).includes(id)||p.items[id]==='80'));if(sk)return call('skill',{id:sk});return call('draw');}
export function handle(s,b){if(b.op==='tick'){let i=s?.players.findIndex(p=>p.token===b.token&&!p.bot);if(i==null||i<0)fail('Phiên đăng nhập không hợp lệ');if(s.phase==='play'&&Date.now()-(s.botAt||0)>=1200){let before=s.rev;s=botStep(s);if(s.rev!==before)s.botAt=Date.now();while(s.pending?.type==='challenge'&&(challengeBlocked(s,s.pending)||!s.players[s.pending.responders[0]].hand.includes('97'))){let j=s.pending.responders[0];s=core(s,{op:'pass',token:s.players[j].token,rev:s.rev}).s;}}return {s,out:{view:view(s,i)}};}let r=core(s,b);if(b.op==='state')return r;let st=r.s;while(st.pending?.type==='challenge'&&(challengeBlocked(st,st.pending)||!st.players[st.pending.responders[0]].hand.includes('97'))){let j=st.pending.responders[0];st=core(st,{op:'pass',token:st.players[j].token,rev:st.rev}).s;}let i=r.out.view.me;return {s:st,out:{...r.out,view:view(st,i)}};}

const MON={120:[7,6,1,'s',2],121:[9,6,3,'s'],122:[8,5,2,'s'],123:[7,4,1,'s',1,'challenge'],124:[6,9,1,'s',0,null,true],125:[13,8,3,'s'],126:[9,6,3,'s'],127:[7,6,4,'s'],128:[7,4,1,'s',1,'magic'],129:[8,4,2,'d2'],130:[8,4,2,'d2'],131:[8,4,2,'d2'],132:[10,6,1,'s'],133:[8,5,2,'s'],134:[11,7,1,'s'],135:[8,4,2,'d2'],136:[8,4,2,'d2'],137:[8,4,2,'d2'],138:[9,6,2,'s'],139:[10,7,3,'s'],140:[7,6,2,'s2'],141:[8,4,2,'d2'],142:[9,6,1,'s',1],143:[9,6,3,'s'],144:[9,6,3,'s'],145:[8,7,4,'s'],146:[7,6,3,'s'],147:[10,7,2,'s'],148:[5,8,1,'s',0,null,true],149:[9,6,2,'s'],170:[8,4,2,'d2'],171:[10,4,1,'s'],172:[7,4,1,'s',1]};
const HERO_CLASS={ '01_Ho_Ve':'guardian','03_Nhac_Si':'bard','04_Than_Rung':'druid','05_Chien_Binh':'warrior','06_Cuong_Chien':'berserker','07_Trieu_Hoi_Su':'necromancer','08_Phap_Su_Den':'dark','cung thu':'ranger','phap su':'wizard','sieu trom':'thief','đấu si':'fighter'};
