const MON_CLASS={121:['guardian','ranger'],125:['bard','thief'],126:['fighter','wizard'],129:['ranger'],130:['thief'],131:['fighter'],135:['wizard'],136:['guardian'],137:['bard'],140:['berserker'],141:['necromancer'],143:['bard','thief'],170:['dark']};
function eligibleTeam(p,id){let r=MON[id],need=MON_CLASS[id]||[],mask={64:'bard',65:'warrior',66:'guardian',67:'wizard',68:'ranger',69:'thief',70:'druid',71:'berserker',72:'necromancer'},remaining=p.party.map(h=>[HERO_CLASS[C[h]?.group],mask[p.items[h]]].filter(Boolean)),leader=LEADER_CLASS[p.leader];if(leader&&p.leaderRole!=='monster'&&p.leaderRole!=='challenge')remaining.push([leader]);function match(k,used){if(k===need.length)return p.party.length-[...used].filter(j=>j<p.party.length).length>=r[2]-need.length;return remaining.some((classes,j)=>!used.has(j)&&classes.includes(need[k])&&match(k+1,new Set([...used,j])));}return match(0,new Set());}
