function beginAttack(s,i,id,n,log){let p=s.players[i],penalty=id==='171'?Math.max(0,p.party.length-1):0;if(penalty)log(p.name+' — Ma Voi Lang Thang: -'+penalty+' xúc xắc');offerRoll(s,{kind:'attack',actor:i,id,total:n+passiveRoll(s,i,'attack',id,log)+(s.bonus||0)+(s.attackBonus||0)-penalty},log);}
function finishAttack(s,i,id,total,log){s.pending={type:'attack',actor:i,id,name:MON_NAMES[id],win:MON[id][0],counter:MON[id][1],reverse:!!MON[id][6],counterHigh:id==='171',total};s.event={seq:s.rev+1,id,kind:'attack',actor:i};log(s.players[i].name+' tấn công '+MON_NAMES[id]+': '+s.pending.total+' điểm');}

const MON_NAMES={"120": "Ong Bắp Cày Rồng", "121": "Goretelodont", "122": "Ác Quỷ Rừng Già", "123": "Thỏ Bông Bị Ám", "124": "Kẻ Xé Rạn San Hô", "125": "Phượng Hoàng Lam", "126": "Griffin Kẻ Săn Mồi", "127": "Song Xà Độc Dược", "128": "Sư Tử Vuốt Lửa", "129": "Ma Mút Hỗn Loạn", "130": "Cú Mèo Chiến Binh", "131": "Rồng Titan", "132": "Dương Thần Băng Giá", "133": "Nữ Hoàng Vực Thẳm", "134": "Rùa Đất Khổng Lồ", "135": "Chó Hai Đầu Orthus", "136": "Bá Vương Rex", "137": "Vua Rồng Hắc Ám", "138": "Rồng Hoang Dã", "139": "Rex Cơ Bắp", "140": "Kẻ Xé Bò Sát", "141": "Kẻ Diệt Vong", "142": "Cá Mập Cổ Đại", "143": "Ác Mộng Móng Vuốt", "144": "Hổ Răng Kiếm Dị Hóa", "145": "Khối Nhầy Khổng Lồ", "146": "Vạc Độc Anuran", "147": "Xà Vương Vương Miện", "148": "Dracos", "149": "Dơi Huyết Ánh", "170": "Cự Lang Hoang Tàn", "171": "Ma Voi Lang Thang", "172": "Xà Hải Ác Độc"};

function passiveRoll(s,i,kind,id,log){let p=s.players[i],n=0;const add=(name,v)=>{if(v){n+=v;log(p.name+' — '+name+': '+(v>0?'+':'')+v+' xúc xắc');}};add('Tộc Trưởng Hiền Triết',p.untilNextRoll||0);if(p.leader==='160')add('Sói Nanh Xuyên',Object.keys(p.items).length);if(kind==='attack'){if(p.leader==='158')add('Mũi Tên Thần Thánh',1);if(p.kills.includes('140'))add(MON_NAMES['140'],2);if(p.kills.includes('142'))add(MON_NAMES['142'],1);}if(kind==='skill'){if(p.leader==='167')add('Bản Nhạc Quyến Rũ',1);if(p.kills.includes('137'))add(MON_NAMES['137'],1);add('Trang bị',({'57':-2,'76':2,'82':4}[p.items[id]]||0));}if(kind==='challenge'){if(p.leader==='159')add('Cú Đấm Của Lý Trí',2);if(p.kills.includes('131'))add(MON_NAMES['131'],1);}if(p.kills.includes('146'))add(MON_NAMES['146'],1);return n;}
function startSkill(s,i,id,n,log){let p=s.players[i],item=p.items[id];if(item==='58'){log('Anh hùng bị phong ấn');return;}offerRoll(s,{kind:'skill',actor:i,id,total:n+(s.bonus||0)+passiveRoll(s,i,'skill',id,log)},log);}
function offerRoll(s,q,log){let p=s.players[q.actor],item=q.kind==='skill'?p.items[q.id]:null,options=[];if(p.leader==='162')options.push({key:'leader',add:1,left:1});if(item==='77')options.push({key:'ring',add:2,left:3});if(item==='83')options.push({key:'feather',add:3,left:1});if(options.length&&p.hand.length){s.pending={...q,type:'rollBoost',options};log(p.name+' có thể điều chỉnh xúc xắc: '+q.total);}else finishRoll(s,q,log);}
function finishRoll(s,q,log){let responders=s.players.map((p,i)=>p.leader==='161'&&!(s.druidUsed||[]).includes(i)?i:-1).filter(i=>i>=0);if(responders.length){s.pending={...q,type:'druidReact',responders};return;}offerModifiers(s,q,log);}
function completeRoll(s,q,log){s.finalRoll={seq:s.rollSeq,total:q.total,actor:q.actor};log(s.players[q.actor].name+' — tổng cuối: '+q.total+' (xúc xắc '+s.dice.join(' + ')+')');if(q.kind==='challenge')finishDuelRoll(s,q,log);else if(q.kind==='attack')finishAttack(s,q.actor,q.id,q.total,log);else skill(s,s.players[q.actor],q.id,q.total,log);}

function modifierValues(q,i,c,s=null){let values=modBase(c.id)==='188'&&q.kind==='attack'&&q.actor===i?[4]:c.values;if(s&&q.actor===i&&s.players[i].leader==='166')return [...new Set(values.flatMap(v=>[v,v+1,v-1]))];return values;}
function modifierEligible(s,i){let h=s.players[i].hand;return !s.noModifiers&&h.some(id=>C[id]?.type==='modifier'&&(!['184','185'].includes(modBase(id))||h.length>1));}
function offerModifiers(s,q,log){q={...q,type:'modifierReact',responders:[]};advanceModifiers(s,q,log,true);}
function advanceModifiers(s,q,log,reset){if(reset)q.responders=s.players.map((_,j)=>(q.actor+j)%s.players.length).filter(j=>modifierEligible(s,j));else q.responders=q.responders.filter(j=>modifierEligible(s,j));if(q.responders.length){s.pending=q;return;}s.pending=null;completeRoll(s,q,log);}
